import hashlib,json,os,pathlib,subprocess,sys,time
R=pathlib.Path(__file__).resolve().parent
ROOT=R.parent
(R/'tmp').mkdir(exist_ok=True)
E=dict(os.environ, PYTHONDONTWRITEBYTECODE='1', TMPDIR=str(R/'tmp'), PYTHONPYCACHEPREFIX=str(R/'pycache'))
def snapshot(name):
    files={}
    for base,dirs,names in os.walk(ROOT):
        if pathlib.Path(base)==ROOT: dirs[:]=[x for x in dirs if x not in ('.git','.review')]
        for n in names:
            p=pathlib.Path(base)/n
            if p.is_symlink(): files[str(p.relative_to(ROOT))]={'link':os.readlink(p)}
            elif p.is_file():
                b=p.read_bytes(); files[str(p.relative_to(ROOT))]={'size':len(b),'sha256':hashlib.sha256(b).hexdigest()}
    git={}
    for cmd in (['rev-parse','HEAD','HEAD^{tree}'],['status','--porcelain=v1','--untracked-files=all','--ignored=matching'],['diff','--binary'],['diff','--cached','--binary']):
        r=subprocess.run(['git',*cmd],cwd=ROOT,capture_output=True);git[' '.join(cmd)]={'rc':r.returncode,'out':r.stdout.decode(),'err':r.stderr.decode()}
    d={'files':files,'git':git};(R/f'snapshot-{name}.json').write_text(json.dumps(d,ensure_ascii=False,indent=1))
    print('SNAPSHOT',name,len(files))
    if name=='end':
        old=json.loads((R/'snapshot-start.json').read_text());delta=[p for p in set(files)|set(old['files']) if files.get(p)!=old['files'].get(p)]
        print('FILE_DELTA',delta)
    return d
def run(name,cmd,timeout=600):
    start=time.time()
    try:
        r=subprocess.run(cmd,cwd=ROOT,env=E,capture_output=True,timeout=timeout)
        rc,out,err=r.returncode,r.stdout,r.stderr
    except subprocess.TimeoutExpired as e: rc,out,err=124,e.stdout or b'',e.stderr or b''
    (R/f'{name}.stdout.txt').write_bytes(out);(R/f'{name}.stderr.txt').write_bytes(err)
    receipt={'command':cmd,'rc':rc,'seconds':time.time()-start,'stdout_sha256':hashlib.sha256(out).hexdigest(),'stderr_sha256':hashlib.sha256(err).hexdigest()}
