for marker in ['reviewed_sha: 7c5742c3bf46a427b1525a86247c7448a6149948','base_sha: 76cf4c51a6b1a5a0f30621c73f9a6f03e7e68138','Reviewed commit: 7c5742c3bf46a427b1525a86247c7448a6149948','ĐỐI CHIẾU LƯỢT TRƯỚC','BẢNG LỚP HIỆN TẠI']:
 assert marker in v,marker
assert 'pending' not in v
head=subprocess.run(['git','rev-parse','HEAD','HEAD^{tree}'],capture_output=True,text=True,check=True).stdout.splitlines()
